CREATE MATERIALIZED VIEW mv_daily_revenue AS
SELECT date_trunc('day', created_at) AS day, merchant_id, SUM(amount_cents) AS total_cents
FROM orders GROUP BY 1, 2;

-- Required for CONCURRENTLY so Postgres can diff old vs new rows
CREATE UNIQUE INDEX idx_mv_daily_rev_pk ON mv_daily_revenue (day, merchant_id);

-- Non-blocking refresh guarded against overlapping cron runs
DO $$
BEGIN
  IF pg_try_advisory_lock(90421) THEN
    REFRESH MATERIALIZED VIEW CONCURRENTLY mv_daily_revenue;
    PERFORM pg_advisory_unlock(90421);
  END IF;
END $$;
```
